DROP TABLE IF EXISTS `member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member` (
  `member_id` bigint NOT NULL AUTO_INCREMENT COMMENT '회원 ID',
  `login_id` varchar(20) NOT NULL COMMENT '로그인 아이디',
  `password` varchar(255) NOT NULL COMMENT '비밀번호',
  `name` varchar(50) NOT NULL COMMENT '이름',
  `role` varchar(20) NOT NULL COMMENT '역할(고객/상담원/관리자)',
  `status` varchar(20) NOT NULL COMMENT '회원 상태(활성/비활성)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '가입 일시',
  PRIMARY KEY (`member_id`),
  UNIQUE KEY `uk_member_login_id` (`login_id`),
  CONSTRAINT `ck_member_role` CHECK ((`role` in (_utf8mb4'CUSTOMER',_utf8mb4'AGENT',_utf8mb4'ADMIN'))),
  CONSTRAINT `ck_member_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'INACTIVE')))
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='회원';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `member` WRITE;
/*!40000 ALTER TABLE `member` DISABLE KEYS */;
INSERT INTO `member` VALUES (1,'admin01','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','관리자','ADMIN','ACTIVE','2026-09-01 09:00:00'),(2,'agent01','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','심소민','AGENT','ACTIVE','2026-09-01 09:00:00'),(3,'agent02','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','유능한','AGENT','ACTIVE','2026-09-01 09:00:00'),(4,'agent03','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','장건웅','AGENT','ACTIVE','2026-09-01 09:00:00'),(5,'agent04','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','한수민','AGENT','ACTIVE','2026-09-01 09:00:00'),(6,'agent05','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','정혜영','AGENT','ACTIVE','2026-09-01 09:00:00'),(7,'user03','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','이영희','CUSTOMER','ACTIVE','2026-09-04 12:00:00'),(8,'user04','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','박철수','CUSTOMER','ACTIVE','2026-09-05 13:00:00'),(9,'user05','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','최지은','CUSTOMER','ACTIVE','2026-09-06 14:00:00'),(10,'user06','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','정우성','CUSTOMER','ACTIVE','2026-09-07 15:00:00'),(11,'user07','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','한소희','CUSTOMER','ACTIVE','2026-09-08 16:00:00'),(12,'user08','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','김민준','CUSTOMER','ACTIVE','2026-10-01 10:00:00'),(13,'user09','$2a$10$m7bA5IzalkWD0iTndk7hC.a7Vfczy3qqQgwzu3sJOJ9OV1i0jnjsC','오하늘','CUSTOMER','ACTIVE','2026-10-02 11:00:00');
