DROP TABLE IF EXISTS `message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message` (
  `message_id` bigint NOT NULL AUTO_INCREMENT COMMENT '메시지 ID',
  `consultation_id` bigint NOT NULL COMMENT '상담 ID',
  `sender_type` varchar(20) NOT NULL COMMENT '발신자 유형',
  `sender_id` bigint DEFAULT NULL COMMENT '발신 회원 ID',
  `content` text NOT NULL COMMENT '메시지 내용(마스킹)',
  `abuse_status` varchar(20) DEFAULT NULL COMMENT '폭언 판정(정상/폭언)',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '발송 일시',
  PRIMARY KEY (`message_id`),
  KEY `fk_message_sender` (`sender_id`),
  KEY `ix_message_consultation_time` (`consultation_id`,`created_at`),
  CONSTRAINT `fk_message_consultation` FOREIGN KEY (`consultation_id`) REFERENCES `consultation` (`consultation_id`),
  CONSTRAINT `fk_message_sender` FOREIGN KEY (`sender_id`) REFERENCES `member` (`member_id`),
  CONSTRAINT `ck_message_abuse_status` CHECK ((`abuse_status` in (_utf8mb4'NORMAL',_utf8mb4'ABUSIVE'))),
  CONSTRAINT `ck_message_sender_type` CHECK ((`sender_type` in (_utf8mb4'CUSTOMER',_utf8mb4'AGENT',_utf8mb4'AI',_utf8mb4'SYSTEM')))
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='메시지';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `message` WRITE;
/*!40000 ALTER TABLE `message` DISABLE KEYS */;
INSERT INTO `message` VALUES (1,1,'AI',NULL,'안녕하세요, AI 상담입니다. 궁금한 내용을 입력하시거나 자주 묻는 질문을 선택해 주세요.',NULL,'2026-09-10 13:00:00.037'),(2,1,'CUSTOMER',8,'주민센터에 낸 민원이 몇 주째 처리가 안 되고 있어요.',NULL,'2026-09-10 13:00:20.074'),(3,1,'AI',NULL,'죄송합니다. 해당 문의에 대한 답변을 찾지 못했어요. 상담원과 직접 상담하시겠어요?',NULL,'2026-09-10 13:00:25.111'),(4,1,'SYSTEM',NULL,'상담원이 연결되었습니다. 이전 AI 상담 내용이 전달되었습니다.',NULL,'2026-09-10 13:02:35.148'),(5,1,'AGENT',4,'안녕하세요, 상담원입니다. 남겨주신 문의 확인했습니다. 조금 더 자세히 말씀해 주시겠어요?',NULL,'2026-09-10 13:02:50.185'),(6,1,'CUSTOMER',8,'네, 오늘 오전에 신청했는데 아직 연락이 없어서요.','NORMAL','2026-09-10 13:03:50.222'),(7,1,'AGENT',4,'확인해 보니 접수는 정상적으로 되어 있습니다. 담당 부서에서 순차적으로 처리 중입니다.',NULL,'2026-09-10 13:05:00.259'),(8,1,'CUSTOMER',8,'*** 아직도 처리 안 됐어요?','ABUSIVE','2026-09-10 13:06:10.296'),(9,1,'SYSTEM',NULL,'[시스템 경고] 부적절한 표현이 감지되었습니다. 상담원 보호 정책에 따라 경고 1회가 부여되었습니다. 같은 상담에서 다시 감지되면 상담이 자동 종료되고 이용이 제한됩니다.',NULL,'2026-09-10 13:06:13.333'),(10,1,'AGENT',4,'고객님, 원활한 상담을 위해 표현을 순화해 주시면 감사하겠습니다.',NULL,'2026-09-10 13:07:03.370'),(11,1,'CUSTOMER',8,'*** 같은 답변 좀 그만하세요.','ABUSIVE','2026-09-10 13:08:03.407'),(12,1,'SYSTEM',NULL,'같은 상담에서 부적절한 표현이 2회 감지되어 상담원 보호 정책에 따라 상담이 자동 종료되었습니다.',NULL,'2026-09-10 13:08:06.444'),(13,2,'AI',NULL,'안녕하세요, AI 상담입니다. 궁금한 내용을 입력하시거나 자주 묻는 질문을 선택해 주세요.',NULL,'2026-09-25 10:30:00.481'),(14,2,'CUSTOMER',8,'구청에 신청한 보조금 지급이 계속 늦어지고 있어요.',NULL,'2026-09-25 10:30:20.518'),(15,2,'AI',NULL,'죄송합니다. 해당 문의에 대한 답변을 찾지 못했어요. 상담원과 직접 상담하시겠어요?',NULL,'2026-09-25 10:30:25.555'),(16,2,'SYSTEM',NULL,'상담원이 연결되었습니다. 이전 AI 상담 내용이 전달되었습니다.',NULL,'2026-09-25 10:32:35.592'),(17,2,'AGENT',2,'안녕하세요, 상담원입니다. 남겨주신 문의 확인했습니다. 조금 더 자세히 말씀해 주시겠어요?',NULL,'2026-09-25 10:32:50.629'),(18,2,'CUSTOMER',8,'네, 오늘 오전에 신청했는데 아직 연락이 없어서요.','NORMAL','2026-09-25 10:33:50.666'),(19,2,'AGENT',2,'확인해 보니 접수는 정상적으로 되어 있습니다. 담당 부서에서 순차적으로 처리 중입니다.',NULL,'2026-09-25 10:35:00.703'),(20,2,'CUSTOMER',8,'***들 일 똑바로 안 해요?','ABUSIVE','2026-09-25 10:36:10.740'),(21,2,'SYSTEM',NULL,'[시스템 경고] 부적절한 표현이 감지되었습니다. 상담원 보호 정책에 따라 경고 1회가 부여되었습니다. 같은 상담에서 다시 감지되